body{background:var(--bg-page);color:var(--text-primary);font-family:'Noto Sans SC',-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",'Segoe UI',sans-serif;line-height:1.8;font-size:15px;-webkit-font-smoothing:antialiased;}
.chapter-container{max-width:880px;margin:0 auto;padding:48px 40px;background:var(--bg-white);}
.chapter-header{background:var(--gradient-header);border-radius:var(--radius-lg);padding:28px 32px;margin-bottom:32px;overflow:hidden;}
.chapter-header h2{color:#fff;font-size:22px;font-weight:700;}
.chapter-guide{background:var(--bg-white);border:1px solid var(--border-light);border-radius:var(--radius-lg);overflow:hidden;margin-bottom:28px;box-shadow:var(--shadow-card);}
.guide-meta{display:flex;flex-wrap:wrap;background:var(--bg-gray-50);border-bottom:1px solid var(--border-light);}
.guide-meta-item{display:flex;align-items:center;gap:6px;padding:11px 18px;font-size:13px;color:var(--text-secondary);border-right:1px solid var(--border-light);}
.guide-body{padding:18px 24px 20px;}
.guide-learn{margin-bottom:14px;}
.guide-learn-label{font-size:13px;font-weight:700;color:var(--primary);letter-spacing:1.5px;margin-bottom:8px;display:block;}
.guide-learn ul{list-style:none;padding:0;margin:0;display:flex;flex-wrap:wrap;gap:4px 24px;}
.guide-learn li{font-size:14px;color:var(--text-secondary);line-height:1.7;padding-left:16px;position:relative;}
.guide-learn li::before{content:'\25B8';position:absolute;left:0;color:var(--accent-light);font-weight:700;font-size:14px;}
.guide-concepts{display:flex;flex-wrap:wrap;gap:8px;}
.guide-concepts-label{font-size:13px;font-weight:700;color:var(--primary);letter-spacing:1.5px;}
.guide-concept-tag{display:inline-block;background:var(--bg-green-50);border:1px solid rgba(77,184,164,0.2);color:var(--primary-dark);padding:3px 12px;border-radius:14px;font-size:13px;font-weight:500;}
.chapter-content{padding:0;}
.chapter-content h3{color:var(--text-primary);font-size:17px;font-weight:700;margin:32px 0 14px 0;padding:10px 16px;background:var(--bg-green-50);border-left:3px solid var(--primary);}
.chapter-content p{color:var(--text-secondary);line-height:1.85;margin-bottom:14px;text-align:justify;}
table{width:100%;border-collapse:separate;border-spacing:0;margin:20px 0;border-radius:var(--radius-md);overflow:hidden;border:1px solid var(--border-light);font-size:14px;}
thead th{background:var(--gradient-header);color:#fff;font-weight:600;padding:11px 16px;text-align:left;font-size:13px;}
tbody td{padding:10px 16px;border-bottom:1px solid var(--border-light);color:var(--text-secondary);}
tbody tr:nth-child(odd){background:var(--bg-white);}tbody tr:nth-child(even){background:var(--bg-gray-50);}
.summary-box{background:var(--bg-white);border:1px solid var(--border-light);border-radius:var(--radius-lg);padding:22px 26px;margin-top:36px;position:relative;box-shadow:var(--shadow-sm);}
.summary-box::before{content:'';position:absolute;top:0;left:0;right:0;height:3px;background:var(--gradient-soft);border-radius:var(--radius-lg) var(--radius-lg) 0 0;}
.summary-box h3{color:var(--primary-dark)!important;border-left:none!important;background:none!important;padding:0!important;margin:0 0 12px 0!important;font-size:15px!important;}
.summary-box ul{list-style:none;padding-left:0;}
.summary-box li{padding-left:20px;position:relative;color:var(--text-secondary);margin-bottom:6px;}
.summary-box li::before{content:'\2192';position:absolute;left:0;color:var(--primary);font-weight:600;}
.tip-box{background:var(--bg-gray-50);border:1px solid var(--border-light);border-left:3px solid var(--primary);border-radius:0 var(--radius-sm) var(--radius-sm) 0;padding:14px 18px;margin:18px 0;}
.tip-box.warning{border-left-color:#f59e0b;background:#fffbeb;}
.tip-box.important{border-left-color:#ef4444;background:#fef2f2;}
.concept-block{background:var(--bg-green-50);border:1px solid rgba(77,184,164,0.15);border-radius:var(--radius-md);padding:18px 22px;margin:18px 0;}
.concept-block h4{color:var(--primary-dark);border-bottom:none;margin-top:0;padding-bottom:4px;}
.question-card{background:var(--bg-white);border:1px solid var(--border-light);border-radius:var(--radius-lg);margin-bottom:24px;overflow:hidden;}
.question-header{background:var(--gradient-header-dark);padding:14px 22px;font-size:15px;font-weight:600;color:#fff;}
.question-section{padding:14px 22px;border-bottom:1px solid var(--border-light);}
.question-section h4{color:var(--primary-dark);font-size:12px;font-weight:700;margin-bottom:6px;text-transform:uppercase;letter-spacing:2px;}
.question-section p{margin-bottom:6px;font-size:14px;}
.question-section.answer-section{background:var(--bg-gray-50);}
.question-section.followup-section{background:var(--bg-green-50);}
.keyword-tags{display:flex;flex-wrap:wrap;gap:6px;}
.keyword-tags .tag{background:var(--bg-green-50);border:1px solid rgba(77,184,164,0.2);color:var(--primary-dark);padding:3px 12px;border-radius:20px;font-size:12px;font-weight:500;}
.question-section.quick-answer{background:linear-gradient(135deg,#ecfdf5,#f0fdf4);border-bottom:1px solid rgba(77,184,164,0.2);}
.question-section.quick-answer h4::before{content:'\26A1 ';}
.question-section.quick-answer p{color:#065f46;font-weight:500;font-size:15px;}
.difficulty-tag{display:inline-block;padding:2px 10px;border-radius:12px;font-size:13px;font-weight:600;}
.diff-beginner{background:#dcfce7;color:#15803d;}
.diff-intermediate{background:#fef3c7;color:#b45309;}
.diff-advanced{background:#fee2e2;color:#dc2626;}
.chapter-nav{display:flex;justify-content:center;align-items:center;gap:12px;margin-top:40px;padding:0 20px;}
.chapter-nav a{display:inline-flex;align-items:center;gap:6px;padding:10px 24px;border-radius:var(--radius-md);font-size:14px;font-weight:600;text-decoration:none;}
.chapter-nav .nav-prev,.chapter-nav .nav-next{background:var(--bg-white);color:var(--primary);border:1px solid rgba(77,184,164,0.25);}
.chapter-nav .nav-catalog{background:var(--gradient-main);color:#fff;border:none;}
.chapter-nav .nav-placeholder{width:120px;}
.page-footer{text-align:center;padding:28px 0 16px 0;color:var(--text-muted);font-size:12px;letter-spacing:1px;border-top:1px solid var(--border-light);margin-top:24px;}
.editor-note{background:linear-gradient(135deg,#eff6ff,#f0f7ff);border:1px solid rgba(59,130,246,0.15);border-left:3px solid #3b82f6;border-radius:0 var(--radius-sm) var(--radius-sm) 0;padding:12px 16px;margin:18px 0;font-size:14px;color:#1e40af;line-height:1.7;}
.editor-note::before{content:'\1F4D6  编者提示';display:inline-block;font-weight:700;font-size:11px;letter-spacing:1.5px;margin-right:8px;padding:1px 7px;background:rgba(59,130,246,0.1);border-radius:3px;color:#2563eb;}
.practice-box{background:linear-gradient(135deg,var(--bg-teal-50) 0%,var(--bg-green-50) 100%);border:1px solid rgba(77,184,164,0.25);border-left:4px solid var(--primary);border-radius:0 var(--radius-md) var(--radius-md) 0;padding:20px 22px;margin:24px 0;}
.practice-box::before{content:'\1F527  动手试一试';display:block;font-weight:700;color:var(--primary-dark);font-size:15px;margin-bottom:10px;padding-bottom:8px;border-bottom:1px dashed rgba(77,184,164,0.25);}
.practice-box ol,.practice-box ul{margin:8px 0 0 0;padding-left:20px;}
.self-check{background:#fefce8;border:1px solid rgba(245,158,11,0.2);border-left:4px solid #f59e0b;border-radius:0 var(--radius-md) var(--radius-md) 0;padding:20px 22px;margin:24px 0;}
.self-check::before{content:'\2753  检验你的理解';display:block;font-weight:700;color:#b45309;font-size:15px;margin-bottom:10px;padding-bottom:8px;border-bottom:1px dashed rgba(245,158,11,0.3);}
.self-check ol{margin:8px 0 0 0;padding-left:20px;counter-reset:check-counter;list-style:none;}
.self-check ol li{counter-increment:check-counter;position:relative;padding-left:8px;color:var(--text-secondary);margin-bottom:10px;line-height:1.7;}
.self-check ol li::before{content:'Q' counter(check-counter);position:absolute;left:-20px;color:#d97706;font-weight:700;font-size:13px;}
.compare-block{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:20px 0;}
.compare-item{background:var(--bg-white);border:1px solid var(--border-light);border-radius:var(--radius-md);padding:16px 18px;}
.compare-item.pros{border-top:3px solid var(--primary);}
.compare-item.cons{border-top:3px solid #f59e0b;}
.compare-item h4{margin-top:0;padding-bottom:5px;border-bottom:none;font-size:14px;}
.compare-item ul{margin:6px 0 0 0;padding-left:16px;}
.compare-item li{font-size:13px;color:var(--text-secondary);margin-bottom:4px;line-height:1.5;}
.scenario-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:20px 0;}
.scenario-card{padding:16px 18px;border-radius:var(--radius-md);border-left:4px solid;}
.scenario-card h4{margin-top:0;font-size:14px;padding-bottom:4px;border-bottom:none;}
.scenario-card ul{margin:6px 0 0 0;padding-left:16px;}
.scenario-card li{font-size:13px;color:var(--text-secondary);margin-bottom:4px;line-height:1.5;}
.scenario-card.blue{border-color:#3b82f6;background:#eff6ff;}
.scenario-card.green{border-color:var(--primary);background:var(--bg-green-50);}
.flowchart{display:flex;align-items:center;justify-content:center;flex-wrap:wrap;margin:20px 0;padding:24px 20px;background:var(--bg-white);border-radius:var(--radius-md);border:1px solid var(--border-light);}
.flow-step{background:var(--bg-green-50);border:1px solid rgba(77,184,164,0.2);border-radius:var(--radius-sm);padding:8px 16px;color:var(--primary-dark);font-size:13px;font-weight:500;text-align:center;}
.flow-arrow{color:var(--primary-light);font-size:18px;margin:0 5px;}

